JET="""{const W7=window.__W();const LIV=(g,lv)=>{const P={neon:0xf4f2ee}[lv];g.traverse(o=>{if(!o.isMesh||!o.material||o.material.transparent||o.material.blending===THREE.AdditiveBlending)return;const m=o.material.clone(),c=m.color;if(c){const l=(c.r+c.g+c.b)/3;if(l>0.08&&!/glass|window|canopy|cockpit/i.test(m.name||"")){c.setHex(P);c.multiplyScalar(0.55+l*0.6);}}if(m.emissive)m.emissive.setHex(0x1a0410);o.material=m;});const bb=new THREE.Box3().setFromObject(g),sx=bb.max.x-bb.min.x,sy=bb.max.y-bb.min.y,sz=bb.max.z-bb.min.z,cy=bb.min.y+sy*0.45,pink=new THREE.MeshBasicMaterial({color:0xff3fa4}),cyan=new THREE.MeshBasicMaterial({color:0x3ff0ff});[-1,1].forEach(sd=>{const st=new THREE.Mesh(new THREE.BoxGeometry(0.08,0.1,sz*0.7),sd>0?pink:cyan);st.position.set((bb.min.x+bb.max.x)/2+sd*Math.min(sx*0.18,1.1),cy,(bb.min.z+bb.max.z)/2);g.add(st);const st2=st.clone();st2.material=sd>0?cyan:pink;st2.position.y=cy-Math.min(0.35,sy*0.12);g.add(st2);});};if(!window.__JET){const g=W7.makeRide('chasse');LIV(g,'neon');W7.jetGear(g,false);if(g.userData.flame)g.userData.flame.visible=true;W7.scene.add(g);window.__JET=g;}window.__JET.visible=false;}"""
TANK="""{const W7=window.__W();const LIV=(g,lv)=>{const P={neon:0xf4f2ee}[lv];g.traverse(o=>{if(!o.isMesh||!o.material||o.material.transparent||o.material.blending===THREE.AdditiveBlending)return;const m=o.material.clone(),c=m.color;if(c){const l=(c.r+c.g+c.b)/3;if(l>0.08&&!/glass|window|canopy|cockpit/i.test(m.name||"")){c.setHex(P);c.multiplyScalar(0.55+l*0.6);}}if(m.emissive)m.emissive.setHex(0x1a0410);o.material=m;});const bb=new THREE.Box3().setFromObject(g),sx=bb.max.x-bb.min.x,sy=bb.max.y-bb.min.y,sz=bb.max.z-bb.min.z,cy=bb.min.y+sy*0.45,pink=new THREE.MeshBasicMaterial({color:0xff3fa4}),cyan=new THREE.MeshBasicMaterial({color:0x3ff0ff});[-1,1].forEach(sd=>{const st=new THREE.Mesh(new THREE.BoxGeometry(0.08,0.1,sz*0.7),sd>0?pink:cyan);st.position.set((bb.min.x+bb.max.x)/2+sd*Math.min(sx*0.18,1.1),cy,(bb.min.z+bb.max.z)/2);g.add(st);const st2=st.clone();st2.material=sd>0?cyan:pink;st2.position.y=cy-Math.min(0.35,sy*0.12);g.add(st2);});};if(!window.__TANK){const g=W7.makeRide('tank');LIV(g,'neon');W7.scene.add(g);window.__TANK=g;}window.__TANK.visible=false;}"""
DROPF="""{const W7=window.__W();if(!window.__DRING){W7.scene.traverse(o=>{if(o.isGroup&&o.children.length===13&&o.children[0].geometry&&o.children[0].geometry.type==='TorusGeometry'&&Math.abs(o.children[0].geometry.parameters.radius-3.4)<0.01)window.__DRING=o;});const r=window.__DRING;if(r){const D={base:3,top:61};Object.defineProperty(r.position,'y',{configurable:true,get:()=>{const T=(performance.now()-(window.__T0||performance.now()))/1000;const t=(window.__DT0||0)+T;const ph=(t%14)/14;return ph<0.5?D.base+(D.top-D.base)*(ph/0.5):ph<0.62?D.top:ph<0.68?D.top-(D.top-D.base)*Math.pow((ph-0.62)/0.06,2):D.base;},set:()=>{}});}}}"""
